-- Love Bot Progressions-Kurve (automatisch generiert)
-- Formel: needed(0,0) = 743, dann je Schritt ceil(prev * 100743 / 100000)
-- Reihenfolge: je Zeile +1 Level, nach Level 743 kommt das naechste Prestige mit Level 0 (dieser Schritt ist der Prestige-Up)

CREATE TABLE IF NOT EXISTS needed_xp_for_lv_or_prestige_up (
  prestige INTEGER NOT NULL,
  level INTEGER NOT NULL,
  needed_xp TEXT NOT NULL,
  total_xp TEXT NOT NULL,
  PRIMARY KEY (prestige, level)
);
